gaQa(){return"Buchhaltungssysteme"},
gaQb(){return"Eine Periode der B\xfccher abschlie\xdfen: Keine Rechnung mit Datum darin kann storniert, keine Zahlung darin zugeordnet werden, und jeder Buchhaltungsexport wird protokolliert. Aus: Nichts wird gesperrt und Exporte werden nicht protokolliert."},
