gaQt(){return"F\xfcr andere buchen"},
gaQu(){return"Admins und Inhaber buchen Pl\xe4tze f\xfcr andere Mitglieder."},
gaQv(){return"Jede Buchungsfl\xe4che \u2014 Plan, Tages-, Wochen- und Monatsansicht, Buchungsblatt, Kiosk, QR- oder NFC-Scan \u2014 pr\xfcft die Verf\xfcgbarkeitsparameter, bevor sie ein Zeitfenster anbietet, und nennt den Grund, wenn sie es nicht kann; geschlossene Tage erscheinen in jeder Ansicht geschlossen, eine Legende benennt die Platzzust\xe4nde, und Admins d\xfcrfen Mitglieder auschecken, wo die Regel es erlaubt."},
gaQw(){return"Buchungspr\xfcfung"},
