gaRZ(){return"Plusieurs factures ouvertes d'un membre peuvent \xeatre regroup\xe9es en une seule qu'il paie. Les originales restent dans l'archive, tra\xe7ables poste par poste, et ne sont plus relanc\xe9es s\xe9par\xe9ment."},
gaS_(){return"Regrouper les factures"},
gaS0(){return"Factures"},
