gaSX(){return"Factures mensuelles, paiements et d\xe9penses."},
gaSY(){return"Plus"},
gaSZ(){return"Envoyer la d\xe9claration de TVA britannique pr\xe9par\xe9e \xe0 HMRC depuis l'application, par Making Tax Digital, et garder l'accus\xe9 de HMRC sur la d\xe9claration. D\xe9sactiv\xe9, seul le fichier de passerelle reste."},
gaT_(){return"D\xe9poser la TVA britannique aupr\xe8s de HMRC"},
gaT0(){return"Sites"},
gaT1(){return"Plusieurs adresses : les \xe9tages sont regroup\xe9s par site, chaque site a son adresse et son SIRET, chaque adh\xe9rent un site de rattachement, et les documents nomment le site concern\xe9. D\xe9sactiv\xe9 : une seule adresse pour l'espace."},
gaT2(){return"Choix de la navigation"},
