gaUE(){return"La tablette \xe0 la porte, les badges et les scans."},
gaUF(){return"Qui fr\xe9quente l'espace, leurs profils et leurs r\xf4les."},
gaUG(){return"Conversations, alertes et ce qui arrive sur le t\xe9l\xe9phone."},
