B.en7=new A.iM("list_workspaces","deskilo_list_workspaces","List my workspaces","Start here. Lists the DesKilo workspaces this person may use through this assistant, each with its workspace_id, name and the operations allowed there. Every other tool needs one of these workspace_id values; when the person has several workspaces, ask which one unless the request makes it obvious.",'{"type":"object","additionalProperties":false,"properties":{"limit":{"type":"integer","minimum":1,"maximum":100,"description":"How many items to return (1-100, default 25).","examples":[25]}},"required":[]}',"read","discovery",B.w,!0,!1)
B.iD=s(["mcpAccess"],t.s)
B.emR=new A.iM("get_capabilities","deskilo_get_capabilities","What can I do here?","What this assistant may do in one workspace right now and until when access is approved, plus the workspace's time zone, currency, opening hours and its named booking periods (morning, afternoon, full_day) with their exact local times. Call it before booking to read \"tomorrow morning\" in the workspace's zone, and when a tool is missing or a call was refused, to explain what is allowed. `refused` names each operation it may not use here and why: not_exposed (the workspace does not offer it), no_consent (the person did not allow it for this assistant), forbidden (the person's role lacks the permission) or target_ceiling (the consent covers only the person's own data).",u.M,"read","workspace",B.iD,!0,!1)
B.emU=new A.iM("get_availability","deskilo_get_availability","Find free places",'Which places can be booked for a time window in a workspace: seats, meeting rooms and parking slots (each booked in its own slot, e.g. an hour for a room), and desks, offices and levels that are booked as a whole, each with its kind and a label naming its level, office, desk and seat (e.g. "Level 2 \xb7 Open space \xb7 Desk 4 \xb7 Seat B") and its level_id/office_id, so a follow-up can filter by level_id, office_id or kind. "free" is the booking engine\'s own verdict for this person (opening hours, booking granularity, limits, blocks, whole-place permission and existing bookings), so a free place\'s own id (seat_id for a seat, desk_id for a desk, office_id for an office, level_id for a level) can be passed to deskilo_create_reservation. Paged: pass next_cursor to see more.','{"type":"object","additionalProperties":false,"properties":{"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"starts_at":{"type":"string","format":"date-time","pattern":"(Z|[+-]\\\\d{2}:\\\\d{2})$","description":"Start of the time you want to book, ISO 8601 with an explicit offset in the workspace\'s time zone, e.g. 2026-10-05T09:00:00+02:00.","examples":["2026-10-05T09:00:00+02:00"]},"ends_at":{"type":"string","format":"date-time","pattern":"(Z|[+-]\\\\d{2}:\\\\d{2})$","description":"End of the time you want to book, ISO 8601 with an explicit offset; at most 31 days after starts_at.","examples":["2026-10-05T13:00:00+02:00"]},"level_id":{"type":"string","format":"uuid","description":"Optional: only places on this level (a level_id from an earlier answer)."},"office_id":{"type":"string","format":"uuid","description":"Optional: only places in this office (an office_id from an earlier answer)."},"kind":{"type":"string","enum":["seat","desk","office","level","room","parking"],"description":"Optional: only places of this kind (seat, a meeting room, a parking slot, or a desk, office or level booked as a whole). Rooms and parking slots are listed only while the workspace has them switched on.","examples":["desk"]},"cursor":{"type":"string","maxLength":400,"description":"The next_cursor of the previous page, to read the next one. Omit for the first page."},"limit":{"type":"integer","minimum":1,"maximum":100,"description":"How many items to return (1-100, default 25).","examples":[25]}},"required":["workspace_id","starts_at","ends_at"]}',"read","workspace",B.iD,!0,!1)
B.emO=new A.iM("list_my_reservations","deskilo_list_my_reservations","List my bookings","The person's own bookings that overlap a window (at most 31 days), oldest first, with reservation_id, a label naming the place, times, status and state_digest. Use it before moving, checking in, checking out or cancelling a booking.",'{"type":"object","additionalProperties":false,"properties":{"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"from":{"type":"string","format":"date-time","pattern":"(Z|[+-]\\\\d{2}:\\\\d{2})$","description":"Window start, ISO 8601 with an explicit offset. The window is at most 31 days.","examples":["2026-10-01T00:00:00+02:00"]},"to":{"type":"string","format":"date-time","pattern":"(Z|[+-]\\\\d{2}:\\\\d{2})$","description":"Window end, ISO 8601 with an explicit offset, after from.","examples":["2026-10-31T23:59:59+01:00"]},"limit":{"type":"integer","minimum":1,"maximum":100,"description":"How many items to return (1-100, default 25).","examples":[25]},"cursor":{"type":"string","maxLength":400,"description":"The next_cursor of the previous page, to read the next one. Omit for the first page."}},"required":["workspace_id","from","to"]}',"read","own",B.iD,!0,!1)
B.emL=new A.iM("get_place","deskilo_get_place","Describe a place","Describe one place: a seat, a desk, an office or a level (by its id from deskilo_get_availability or deskilo_list_my_reservations), or one of the person's own reservations by reservation_id. Answers what it is, where it sits (level, office, desk), how many seats it has and what a seat offers. It never includes a picture by default: set include_image to true ONLY when the person explicitly asks to see an image, picture, plan or map; the answer then carries a floor-plan picture with that place highlighted. It also carries the person's favourite mark and the place's rating.",'{"type":"object","additionalProperties":false,"properties":{"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"reservation_id":{"type":"string","format":"uuid","description":"One of the person\'s own reservations (a reservation_id from deskilo_list_my_reservations): describes the place it is for."},"seat_id":{"type":"string","format":"uuid","description":"A seat_id from deskilo_get_availability."},"desk_id":{"type":"string","format":"uuid","description":"A desk_id."},"office_id":{"type":"string","format":"uuid","description":"An office_id."},"level_id":{"type":"string","format":"uuid","description":"A level_id."},"include_image":{"type":"boolean","description":"False by default. True ONLY when the person explicitly asked for an image, picture, plan or map of the place: the answer then carries a floor-plan picture with the place highlighted. Never set it on your own initiative.","examples":[false]}},"required":["workspace_id"]}',"read","own",B.iD,!0,!1)
B.a3l=s(["mcpAccess","placeFeedback"],t.s)
B.enk=new A.iM("list_my_favorites","deskilo_list_my_favorites","My favourite places","The places this person marked as favourites in one workspace (seats, desks, offices, levels), each with its label, its kind, its id and its rating (average, how many rated, and the person's own). To book one, pass its id to deskilo_create_reservation (seat_id, desk_id, office_id or level_id by kind) with the usual date and period or times.",u.M,"read","own",B.a3l,!0,!1)
B.Q0=s(["mcpAccess","moneyTab"],t.s)
B.emN=new A.iM("get_my_statement","deskilo_get_my_statement","My monthly statement","The person's own statement for one month: subscription fee, included and used half-days, overage, supplements, credits, balance and VAT. Amounts are integer minor units (cents) of `currency`.",'{"type":"object","additionalProperties":false,"properties":{"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"period":{"type":"string","pattern":"^\\\\d{4}-(0[1-9]|1[0-2])$","description":"The month, as YYYY-MM.","examples":["2026-09"]}},"required":["workspace_id","period"]}',"read","own",B.Q0,!0,!1)
B.enh=new A.iM("get_member_statement","deskilo_get_member_statement","A member's monthly statement","One member's statement for one month, as the app shows it to someone allowed to view the workspace's finances: subscription fee, included and used half-days, overage, supplements, credits, balance and VAT. Amounts are integer minor units (cents) of `currency`. For the person's own statement use deskilo_get_my_statement.",'{"type":"object","additionalProperties":false,"properties":{"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"member_id":{"type":"string","format":"uuid","description":"The member whose statement to read: a member_id of this workspace.","examples":["00000000-0000-4000-8000-0000000000d1"]},"period":{"type":"string","pattern":"^\\\\d{4}-(0[1-9]|1[0-2])$","description":"The month, as YYYY-MM.","examples":["2026-09"]}},"required":["workspace_id","member_id","period"]}',"read","workspace",B.Q0,!0,!1)
B.Q_=s(["mcpAccess","invoicing"],t.s)
B.ena=new A.iM("list_my_invoices","deskilo_list_my_invoices","List my invoices","The person's own invoices, newest first: number, period, kind, total in minor units (cents) with its currency, issue time and whether it was voided. Paged.",u.nn,"read","own",B.Q_,!0,!1)
B.emW=new A.iM("create_reservation","deskilo_create_reservation","Book a place",'Book a place for the person: a seat (usually a seat_id from deskilo_get_availability), or a whole desk, office or level where the workspace allows it. The workspace\'s own rules apply exactly as in the app; a refusal says why in plain words. Generate a new request_id per booking; resending the same request_id never books twice. To book "the full day", "the morning" or "the afternoon" give date and period instead of times: the workspace\'s own booking periods (see deskilo_get_capabilities, booking_periods) are applied exactly.','{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"seat_id":{"type":"string","format":"uuid","description":"The seat to book: a seat_id from deskilo_get_availability with free = true."},"desk_id":{"type":"string","format":"uuid","description":"Book a whole desk instead of one seat (only where the workspace books desks as a whole)."},"office_id":{"type":"string","format":"uuid","description":"Book a whole office instead of one seat (only where the workspace books offices as a whole)."},"level_id":{"type":"string","format":"uuid","description":"Book a whole level instead of one seat (only where the workspace books levels as a whole)."},"starts_at":{"type":"string","format":"date-time","pattern":"(Z|[+-]\\\\d{2}:\\\\d{2})$","description":"Start, ISO 8601 with an explicit offset in the workspace\'s time zone, e.g. 2026-10-05T09:00:00+02:00. Optional when date and period are given.","examples":["2026-10-05T09:00:00+02:00"]},"ends_at":{"type":"string","format":"date-time","pattern":"(Z|[+-]\\\\d{2}:\\\\d{2})$","description":"End, ISO 8601 with an explicit offset, after starts_at. Optional when date and period are given.","examples":["2026-10-05T13:00:00+02:00"]},"date":{"type":"string","maxLength":500,"description":"The local day to book, YYYY-MM-DD in the workspace\'s time zone. Use with period instead of starts_at/ends_at.","examples":["2026-10-28"]},"period":{"type":"string","enum":["morning","afternoon","full_day"],"description":"A booking period of the workspace, named in get_capabilities (booking_periods) with its exact local times: morning, afternoon or the full working day. Use with date; the server turns it into the workspace\'s exact times, so never compute them yourself.","examples":["full_day"]},"check_in":{"type":"boolean","description":"True to check the person in at once (only when the booking starts now). Default false.","examples":[false]}},"required":["request_id","workspace_id"]}',"write","own",B.iD,!1,!1)
B.enc=new A.iM("update_reservation","deskilo_update_reservation","Move my booking",'Change the start and end of one of the person\'s own bookings. The workspace\'s rules apply as in the app. To book "the full day", "the morning" or "the afternoon" give date and period instead of times: the workspace\'s own booking periods (see deskilo_get_capabilities, booking_periods) are applied exactly.','{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"reservation_id":{"type":"string","format":"uuid","description":"A reservation_id from deskilo_list_my_reservations."},"starts_at":{"type":"string","format":"date-time","pattern":"(Z|[+-]\\\\d{2}:\\\\d{2})$","description":"The new start, ISO 8601 with an explicit offset. Optional when date and period are given.","examples":["2026-10-05T09:00:00+02:00"]},"ends_at":{"type":"string","format":"date-time","pattern":"(Z|[+-]\\\\d{2}:\\\\d{2})$","description":"The new end, ISO 8601 with an explicit offset. Optional when date and period are given.","examples":["2026-10-05T13:00:00+02:00"]},"date":{"type":"string","maxLength":500,"description":"The local day to book, YYYY-MM-DD in the workspace\'s time zone. Use with period instead of starts_at/ends_at.","examples":["2026-10-28"]},"period":{"type":"string","enum":["morning","afternoon","full_day"],"description":"A booking period of the workspace, named in get_capabilities (booking_periods) with its exact local times: morning, afternoon or the full working day. Use with date; the server turns it into the workspace\'s exact times, so never compute them yourself.","examples":["full_day"]},"expected_state":{"type":"string","maxLength":64,"description":"Optional: the state_digest you last read for this reservation. If it changed since, nothing happens and the answer is a conflict carrying the current state."}},"required":["request_id","workspace_id","reservation_id"]}',"write","own",B.iD,!1,!0)
B.en2=new A.iM("check_in","deskilo_check_in","Check in","Check the person in on one of their own bookings (usually today's, from deskilo_list_my_reservations).",u.ot,"write","own",B.iD,!1,!1)
