B.emK=new A.iM("cancel_reservation","deskilo_cancel_reservation","Cancel a booking","Cancel one of the person's own bookings that has NOT started yet, directly: it is cancelled at once and the place is free again (status completed). A booking that already started cannot be cancelled this way; for that use deskilo_request_reservation_deletion. Resending the same request_id never cancels twice.",u.ot,"write","own",B.iD,!1,!0)
B.emS=new A.iM("set_favorite","deskilo_set_favorite","Favourite or unfavourite a place","Mark a place as one of this person's favourites, or take it back (favorite false). Generate a new request_id per call; resending the same one never acts twice.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"kind":{"type":"string","enum":["seat","desk","office","level"],"description":"What kind of place: a seat, a desk, an office or a level.","examples":["seat"]},"resource_id":{"type":"string","format":"uuid","description":"The place\'s id, from deskilo_get_availability, deskilo_list_my_favorites or deskilo_get_place.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"favorite":{"type":"boolean","description":"True (default) to mark it as a favourite, false to take it back.","examples":[true]}},"required":["request_id","workspace_id","kind","resource_id"]}',"write","own",B.a3l,!1,!0)
B.en5=new A.iM("rate_place","deskilo_rate_place","Rate a place","Give a place 0 to 5 stars on this person's behalf, or take their rating back (clear true). Only when the person asks to rate. Generate a new request_id per call; resending the same one never acts twice.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"kind":{"type":"string","enum":["seat","desk","office","level"],"description":"What kind of place: a seat, a desk, an office or a level.","examples":["seat"]},"resource_id":{"type":"string","format":"uuid","description":"The place\'s id, from deskilo_get_availability, deskilo_list_my_favorites or deskilo_get_place.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"stars":{"type":"integer","minimum":0,"maximum":5,"description":"The rating, from 0 to 5 stars. Omit with clear true to take the rating back.","examples":[4]},"clear":{"type":"boolean","description":"True to take the person\'s rating back instead of giving stars.","examples":[false]}},"required":["request_id","workspace_id","kind","resource_id"]}',"write","own",B.a3l,!1,!0)
B.enj=new A.iM("request_reservation_deletion","deskilo_request_reservation_deletion","Ask to delete a started booking","Ask to delete one of the person's own bookings that has ALREADY started. Depending on the workspace's validation rules it is deleted at once (status completed) or a validator must approve it first (status pending_validation: tell the person it is not deleted yet). A booking that has not started is cancelled directly with deskilo_cancel_reservation instead.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"reservation_id":{"type":"string","format":"uuid","description":"A reservation_id from deskilo_list_my_reservations."},"reason":{"type":"string","maxLength":500,"description":"Optional: why the booking is cancelled, shown to whoever validates it."},"expected_state":{"type":"string","maxLength":64,"description":"Optional: the state_digest you last read for this reservation. If it changed since, nothing happens and the answer is a conflict carrying the current state."}},"required":["request_id","workspace_id","reservation_id"]}',"request","own",B.iD,!1,!0)
B.emQ=new A.iM("request_invoice_issue","deskilo_request_invoice_issue","Request an invoice","Staff only: ask for a member's invoice for one month to be issued. Needs the person's confirmation in the DesKilo app first (status requires_confirmation), then the workspace's validation rules.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"member_id":{"type":"string","format":"uuid","description":"The member this request is about."},"period":{"type":"string","pattern":"^\\\\d{4}-(0[1-9]|1[0-2])$","description":"The month, as YYYY-MM.","examples":["2026-09"]},"kind":{"type":"string","enum":["full","subscription","usage"],"description":"Which invoice: full (subscription and usage), subscription only, or usage only.","examples":["full"]}},"required":["request_id","workspace_id","member_id","period"]}',"request","workspace",B.Q_,!1,!1)
B.en4=new A.iM("request_invoice_void","deskilo_request_invoice_void","Request an invoice void","Staff only: ask for an invoice to be voided. Needs the person's confirmation in the DesKilo app first, then the workspace's validation rules.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"invoice_id":{"type":"string","format":"uuid","description":"The invoice this request is about."},"reason":{"type":"string","maxLength":500,"description":"Why the invoice should be voided, shown to whoever validates it."}},"required":["request_id","workspace_id","invoice_id"]}',"request","workspace",B.Q_,!1,!0)
B.en6=new A.iM("request_refund","deskilo_request_refund","Request a refund","Staff only: ask for an invoice to be refunded. Needs the person's confirmation in the DesKilo app first, then the workspace's validation rules.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"invoice_id":{"type":"string","format":"uuid","description":"The invoice this request is about."},"note":{"type":"string","maxLength":500,"description":"Optional: a note for whoever validates the refund."}},"required":["request_id","workspace_id","invoice_id"]}',"request","workspace",B.Q_,!1,!0)
B.emX=new A.iM("request_member_status_change","deskilo_request_member_status_change","Request a member status change","Staff only: ask for a member to become active, paused or exited. Needs the person's confirmation in the DesKilo app first, then the workspace's validation rules.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"member_id":{"type":"string","format":"uuid","description":"The member this request is about."},"status":{"type":"string","enum":["active","paused","exited"],"description":"The member status to request.","examples":["paused"]}},"required":["request_id","workspace_id","member_id","status"]}',"request","workspace",B.iD,!1,!0)
B.eni=new A.iM("request_subscription_change","deskilo_request_subscription_change","Request a subscription change","Staff only: ask for a member's subscription share (percent) to change. Needs the person's confirmation in the DesKilo app first, then the workspace's validation rules.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"member_id":{"type":"string","format":"uuid","description":"The member this request is about."},"pct":{"type":"integer","minimum":0,"maximum":100,"description":"The subscription share to request, in percent (0-100).","examples":[50]}},"required":["request_id","workspace_id","member_id","pct"]}',"request","workspace",B.iD,!1,!0)
B.emT=new A.iM("list_pending_validations","deskilo_list_pending_validations","List requests awaiting a decision","Requests in this workspace that are waiting for a decision: the ones the person made or is the subject of and, when the person's consent reaches the whole workspace, the ones they may decide. Paged.",u.nn,"read","own",B.iD,!0,!1)
B.emJ=new A.iM("get_validation","deskilo_get_validation","Read one request awaiting a decision","One request awaiting a decision: its type, who decided so far, whether this person can respond, and if not, why.",'{"type":"object","additionalProperties":false,"properties":{"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"event_id":{"type":"string","format":"uuid","description":"An event_id from deskilo_list_pending_validations."}},"required":["workspace_id","event_id"]}',"read","own",B.iD,!0,!1)
B.end=new A.iM("respond_to_validation","deskilo_respond_to_validation","Accept or refuse a request","Accept or refuse a request awaiting this person's decision. Needs the person's confirmation in the DesKilo app first (status requires_confirmation). The workspace's quorum still decides whether the request is settled.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"event_id":{"type":"string","format":"uuid","description":"An event_id from deskilo_list_pending_validations."},"accept":{"type":"boolean","description":"True to accept, false to refuse.","examples":[true]}},"required":["request_id","workspace_id","event_id","accept"]}',"decision","workspace",B.iD,!1,!0)
B.ll=s(["mcpAccess","setupGuide"],t.s)
B.ene=new A.iM("get_setup_status","deskilo_get_setup_status","How far is the space's setup?","For someone who configures the workspace: every setup step with its state (ready, needs_configuration, blocked, needs_operator, deferred, not_applicable), the milestones in order (bookable, money, invoice, live) with how many of their required steps are ready, next_milestone and next_step (the one thing to do now), the current level of each process, and per step what an assistant may do (`assistant`): mark_done (only the person can tell it is done), set_aside (optional: it can wait), in_app (the person does it on the app screen named by `route`), in_app_only (it takes credentials such as payment or e-invoicing keys: never ask for them, send the person to that screen) or none. Read only.",u.M,"read","workspace",B.ll,!0,!1)
B.emM=new A.iM("list_setup_levels","deskilo_list_setup_levels","The setup levels","The levels each process can be set to (bookings, community, money, payments, tax, purchases, presentation, operations, assistant), lowest first, with the features each level adds and the level of another process it needs; the three quick starts (essentiel, standard, complet); and the space's current level of each process (`current`). Read only: deskilo_preview_setup_levels says what a choice would switch on and off.",u.M,"read","workspace",B.ll,!0,!1)
B.eng=new A.iM("explain_setup_step","deskilo_explain_setup_step","What a setup step is","For someone who configures the workspace: one setup step (or, without step, every step in the guide's order) as the guide defines it: its group, milestone, the app screen that sets it up (`route`), whether it is required, the steps it waits for (`depends_on`) and the steps that wait for it (`unlocks`), the feature it belongs to, who does it (`actor`), how long it takes, whether it takes credentials (`takes_credentials`: then only the person enters them, in the app), its state now and what an assistant may do about it (`assistant`, as in deskilo_get_setup_status). Read only.",'{"type":"object","additionalProperties":false,"properties":{"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"step":{"type":"string","enum":["basics","hours","places","member_rights","invite","pricing","services","payment_methods","online_payments","approvals","new_members","notifications","limits","kiosk","purchases","lease","assets","look","public_page","legal_identity","vat","numbering","documents","einvoicing","accounting","reminders","first_booking","recovery","assistant"],"description":"The step id, from deskilo_get_setup_status; leave it out for every step.","examples":["hours"]}},"required":["workspace_id"]}',"read","workspace",B.ll,!0,!1)
B.en_=new A.iM("preview_setup_levels","deskilo_preview_setup_levels","Preview a change of levels","What choosing levels would change, without changing anything: per process `changes` (from, to), the features switched on and off, and `gaps` (a chosen level that needs a higher level of another process: raise that one too). Name a preset, single processes, or both; a process left out keeps its level. Show the person this answer, in words, before deskilo_apply_setup_levels with the same choice. ready_to_apply is false when there is a gap or nothing changes.",'{"type":"object","additionalProperties":false,"properties":{"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"preset":{"type":"string","enum":["essentiel","standard","complet"],"description":"A quick start: essentiel (bookings and statements, no invoices or VAT), standard or complet. A process named alongside overrides its level.","examples":["essentiel"]},"bookings":{"type":"string","enum":["simple","resources","measured"],"description":"The level of bookings, lowest first: simple, resources, measured. Left out: it keeps its level."},"community":{"type":"string","enum":["basic","organised"],"description":"The level of community, lowest first: basic, organised. Left out: it keeps its level."},"money":{"type":"string","enum":["none","statements","invoices"],"description":"The level of money, lowest first: none, statements, invoices. Left out: it keeps its level."},"payments":{"type":"string","enum":["off","online"],"description":"The level of payments, lowest first: off, online. Left out: it keeps its level."},"tax":{"type":"string","enum":["none","vat","books"],"description":"The level of tax, lowest first: none, vat, books. Left out: it keeps its level."},"purchases":{"type":"string","enum":["none","expenses","full"],"description":"The level of purchases, lowest first: none, expenses, full. Left out: it keeps its level."},"presentation":{"type":"string","enum":["basic","branded","public"],"description":"The level of presentation, lowest first: basic, branded, public. Left out: it keeps its level."},"operations":{"type":"string","enum":["basic","insight","advanced"],"description":"The level of operations, lowest first: basic, insight, advanced. Left out: it keeps its level."},"assistant":{"type":"string","enum":["off","on"],"description":"The level of assistant, lowest first: off, on. Left out: it keeps its level."}},"required":["workspace_id"]}',"read","workspace",B.ll,!0,!1)
B.en1=new A.iM("apply_setup_levels","deskilo_apply_setup_levels","Change the setup levels","Sets the levels exactly as deskilo_preview_setup_levels showed them (pass the same choice). Needs the person's confirmation in the DesKilo app first (status requires_confirmation): they see every feature switched on and off; then call again with the same request_id and arguments. A lower level hides features and keeps their data. Refused when the choice has a gap or changes nothing; a change to the space's features in the meantime makes the confirmation stale: preview again with a new request_id.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"preset":{"type":"string","enum":["essentiel","standard","complet"],"description":"A quick start: essentiel (bookings and statements, no invoices or VAT), standard or complet. A process named alongside overrides its level.","examples":["essentiel"]},"bookings":{"type":"string","enum":["simple","resources","measured"],"description":"The level of bookings, lowest first: simple, resources, measured. Left out: it keeps its level."},"community":{"type":"string","enum":["basic","organised"],"description":"The level of community, lowest first: basic, organised. Left out: it keeps its level."},"money":{"type":"string","enum":["none","statements","invoices"],"description":"The level of money, lowest first: none, statements, invoices. Left out: it keeps its level."},"payments":{"type":"string","enum":["off","online"],"description":"The level of payments, lowest first: off, online. Left out: it keeps its level."},"tax":{"type":"string","enum":["none","vat","books"],"description":"The level of tax, lowest first: none, vat, books. Left out: it keeps its level."},"purchases":{"type":"string","enum":["none","expenses","full"],"description":"The level of purchases, lowest first: none, expenses, full. Left out: it keeps its level."},"presentation":{"type":"string","enum":["basic","branded","public"],"description":"The level of presentation, lowest first: basic, branded, public. Left out: it keeps its level."},"operations":{"type":"string","enum":["basic","insight","advanced"],"description":"The level of operations, lowest first: basic, insight, advanced. Left out: it keeps its level."},"assistant":{"type":"string","enum":["off","on"],"description":"The level of assistant, lowest first: off, on. Left out: it keeps its level."}},"required":["request_id","workspace_id"]}',"write","workspace",B.ll,!1,!1)
B.en8=new A.iM("mark_setup_step","deskilo_mark_setup_step","Mark a setup step done or for later","For a step deskilo_get_setup_status lists with assistant mark_done (the server cannot verify it: it becomes done) or set_aside (optional: it waits for later and stops counting as open). Needs the person's confirmation in the DesKilo app first (status requires_confirmation), then call again with the same request_id and arguments. A step the server verifies from the space's data is never marked done this way, and a step that takes credentials is never acted on by an assistant.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"step":{"type":"string","enum":["invite","services","new_members","notifications","limits","kiosk","purchases","lease","assets","look","public_page","documents","reminders","recovery","assistant"],"description":"The step id, from deskilo_get_setup_status.","examples":["new_members"]}},"required":["request_id","workspace_id","step"]}',"write","workspace",B.ll,!1,!1)
B.emY=new A.iM("set_workspace_basics","deskilo_set_workspace_basics","Set the workspace time zone, language and address","The setup step 'basics', as its screen does it: the workspace time zone (an IANA name such as Europe/Paris), its default language (en, fr, de, es or it) and its address. Give only what changes. The country and the currency are not offered here: they fix money and legal rules and stay in the app. Needs the person's confirmation in the DesKilo app first (status requires_confirmation): the app shows exactly what changes; then call again with the same request_id and arguments. A change made in the meantime makes the proposal stale: preview again with a new request_id.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"timezone":{"type":"string","maxLength":64,"description":"The workspace time zone as an IANA name, e.g. \\"Europe/Paris\\".","examples":["Europe/Paris"]},"default_locale":{"type":"string","maxLength":5,"description":"The default language of the workspace: en, fr, de, es or it.","examples":["fr"]},"address":{"type":"string","maxLength":300,"description":"The workspace\'s postal address on one line.","examples":["12 rue de la Gare, 34120 P\xe9zenas"]}},"required":["request_id","workspace_id"]}',"write","workspace",B.ll,!1,!1)
B.emP=new A.iM("set_member_permissions_preset","deskilo_set_member_permissions_preset","Let members book and use the space","The setup step 'member_rights', as its screen does it: the preset 'members_can_book' gives the members role the everyday set (book a place, see the calendar, write messages, see their own account), one permission at a time, as a request. Nothing administrative is ever part of it. Needs the person's confirmation in the DesKilo app first (status requires_confirmation): the app lists each permission that will be granted; then call again with the same request_id and arguments. When the workspace requires validation of role changes the result is pending_validation: the requests wait for the validators, and you never approve them.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"preset":{"type":"string","enum":["members_can_book"],"description":"The preset to apply; the only one is \'members_can_book\'.","examples":["members_can_book"]}},"required":["request_id","workspace_id","preset"]}',"write","workspace",B.ll,!1,!1)
B.enb=new A.iM("create_invitations","deskilo_create_invitations","Invite a person to the workspace","The setup step 'invite': an invitation for one member, named by first and last name (at least one). It is never an admin invitation and the join code is never returned to you: the person who confirms sees it in the DesKilo app and passes it on. Needs the person's confirmation in the DesKilo app first (status requires_confirmation): the app shows who is invited; then call again with the same request_id and arguments. The answer names the invitation (invitation_id) and its status, nothing that lets anyone join.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"first_name":{"type":"string","maxLength":120,"description":"The first name of the person to invite.","examples":["Camille"]},"last_name":{"type":"string","maxLength":120,"description":"The last name of the person to invite.","examples":["Martin"]}},"required":["request_id","workspace_id"]}',"write","workspace",B.ll,!1,!1)
B.en9=new A.iM("set_opening_hours","deskilo_set_opening_hours","Set the opening days and hours","The setup step 'hours', as its screen does it: the weekdays members can book and the working day (start, half-day boundary, end, in minutes after midnight on the workspace clock: 08:00 = 480). Give only what changes; the result must keep at least one open weekday and start < boundary < end. The half-day and full-day booking periods follow these hours. Needs the person's confirmation in the DesKilo app first (status requires_confirmation): the app shows exactly what changes; then call again with the same request_id and arguments. A change made in the meantime makes the proposal stale: preview again with a new request_id.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"open_weekdays":{"type":"string","maxLength":20,"description":"The open weekdays as ISO numbers separated by commas, 1 = Monday to 7 = Sunday, e.g. \\"1,2,3,4,5\\".","examples":["1,2,3,4,5"]},"work_start_minutes":{"type":"integer","minimum":0,"maximum":1440,"description":"When the working day starts, in minutes after midnight (08:00 = 480).","examples":[480]},"half_boundary_minutes":{"type":"integer","minimum":0,"maximum":1440,"description":"Where the morning ends and the afternoon starts, in minutes after midnight (12:00 = 720).","examples":[720]},"work_end_minutes":{"type":"integer","minimum":0,"maximum":1440,"description":"When the working day ends, in minutes after midnight (17:00 = 1020).","examples":[1020]}},"required":["request_id","workspace_id"]}',"write","workspace",B.ll,!1,!1)
B.emZ=new A.iM("add_closure_days","deskilo_add_closure_days","Add closure days","Closure days (holidays, a closed week) on which nothing can be booked, as the hours step adds them: dates on the workspace calendar, YYYY-MM-DD separated by commas, with one optional reason. A day already closed is left as it is; removing a closure stays in the app. Needs the person's confirmation in the DesKilo app first (status requires_confirmation): the app shows exactly what changes; then call again with the same request_id and arguments. A change made in the meantime makes the proposal stale: preview again with a new request_id.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"days":{"type":"string","maxLength":400,"description":"The days to close, YYYY-MM-DD separated by commas, e.g. \\"2026-12-24,2026-12-31\\".","examples":["2026-12-24,2026-12-31"]},"reason":{"type":"string","maxLength":200,"description":"Optional: why the space is closed, shown beside the days.","examples":["Christmas"]}},"required":["request_id","workspace_id","days"]}',"write","workspace",B.ll,!1,!1)
B.en3=new A.iM("set_number_sequence","deskilo_set_number_sequence","Set how documents are numbered","The setup step 'numbering', as the number series editor does it, for one journal: prefix, suffix, which part of the date the number prints, its digits, when it restarts, and the next number. Give only what changes. A number restarts at most as often as it prints its date (none: never; year: never or yearly; year_month: any), a series never goes backwards, and a series that already issued numbers cannot drop its date unless the prefix or suffix changes too. Needs the person's confirmation in the DesKilo app first (status requires_confirmation): the app shows exactly what changes; then call again with the same request_id and arguments. A change made in the meantime makes the proposal stale: preview again with a new request_id.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"journal":{"type":"string","enum":["invoice","credit_note","vat_declaration","member","payment"],"description":"The series to change.","examples":["invoice"]},"prefix":{"type":"string","maxLength":16,"description":"Printed before the number, e.g. \\"INV-\\".","examples":["INV-"]},"suffix":{"type":"string","maxLength":16,"description":"Printed after the number.","examples":[""]},"date_part":{"type":"string","enum":["none","year","year_month"],"description":"Which part of the date the number prints.","examples":["year"]},"digits":{"type":"integer","minimum":1,"maximum":9,"description":"How many digits the counter prints, padded with zeros.","examples":[4]},"reset":{"type":"string","enum":["never","yearly","monthly"],"description":"When the counter starts again at 1.","examples":["yearly"]},"next_value":{"type":"integer","minimum":1,"maximum":999999999,"description":"The next number to issue; never below the current one.","examples":[1]}},"required":["request_id","workspace_id","journal"]}',"write","workspace",B.ll,!1,!1)
B.en0=new A.iM("create_membership_plan","deskilo_create_membership_plan","Offer a new membership plan","A membership plan is a subscription level: the percentage of the full subscription a member can choose, as the owner adds it on the billing screen. Give the percentage as a whole number; the range the workspace allows comes from its template and anything outside it, or a plan already offered, is refused. Needs the person's confirmation in the DesKilo app first (status requires_confirmation): the app shows the percentage and the workspace; then call again with the same request_id and arguments. Needs the money functionality to be on in the workspace. The answer says whether the plan was created and at which percentage.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"percent":{"type":"integer","description":"The share of the full subscription the plan charges, as a whole percentage (30 for a plan at 30 % of the full price).","examples":[30]}},"required":["request_id","workspace_id","percent"]}',"write","workspace",B.Q0,!1,!1)
B.emV=new A.iM("set_payment_instructions","deskilo_set_payment_instructions","Change the workspace's bank account","The bank account members are asked to pay into on an unpaid statement, as the Payment methods screen holds it: the IBAN, the BIC, the bank name and, where a country banks without an IBAN, the account number and the bank code (and, in Switzerland, the QR-IBAN). Give only what changes; an empty value clears a field. The IBAN, the BIC and the QR-IBAN are checked before anyone is asked. Needs the person's confirmation in the DesKilo app first (status requires_confirmation): the app shows the workspace, the account as it is now and the account as it would become, and the owners are told afterwards in their notifications that it changed. A change made in the meantime makes the proposal stale: propose again with a new request_id. Other ways to pay (PayPal, Wero, Lydia, Wise) and every payment-provider key or token stay in the app. Needs the money functionality to be on in the workspace. The answer only says that the account changed.",'{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"iban":{"type":"string","maxLength":42,"description":"The IBAN of the account, with or without spaces. An empty value clears it.","examples":["FR76 3000 6000 0112 3456 7890 189"]},"bic":{"type":"string","maxLength":11,"description":"The BIC (SWIFT code) of the bank, 8 or 11 characters. An empty value clears it.","examples":["AGRIFRPP"]},"bank_name":{"type":"string","maxLength":120,"description":"The name of the bank. An empty value clears it.","examples":["Credit Agricole"]},"account_number":{"type":"string","maxLength":40,"description":"The account number, for a country that does not bank by IBAN. An empty value clears it.","examples":["12345678"]},"bank_code":{"type":"string","maxLength":40,"description":"The code that routes to the bank where there is no IBAN: a UK sort code, a US routing number, a Canadian transit and institution number. An empty value clears it.","examples":["20-00-00"]},"qr_iban":{"type":"string","maxLength":42,"description":"Switzerland only: the QR-IBAN a QR-bill is paid into (institution identifier 30000 to 31999). An empty value clears it.","examples":["CH44 3199 9123 0008 8901 2"]}},"required":["request_id","workspace_id"]}',"write","workspace",B.Q0,!1,!1)
